"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52524"],{59882(n){n.exports=JSON.parse('{"id":"FIN-339","slug":"investment-bank","term":"Investment Bank","also_known_as":[],"difficulty":"Intermediate","definition":"An investment bank is a financial institution that helps companies and governments raise money in financial markets, advises on mergers and acquisitions, and trades securities.","explanation":["Unlike commercial banks, investment banks do not mainly take deposits from the public and make everyday loans. Their work centres on large financial transactions.","A key role is underwriting. When a company wants to raise money by selling shares in an initial public offering or by issuing bonds, an investment bank helps price the securities, prepare documents and find investors, often guaranteeing to buy any that remain unsold.","Investment banks also advise companies on mergers and acquisitions, helping them buy, sell or combine businesses and negotiate terms. Many have trading divisions that buy and sell shares, bonds, currencies and derivatives for clients and for themselves, and research teams that analyse companies and markets.","For example, an investment bank might advise a company on buying a competitor for 2 billion and then help it raise the money by issuing bonds.","Investment banks earn fees for advice and underwriting, and profits from trading. Many large banking groups combine investment banking with commercial and retail banking."],"note":"","total":1725,"prev":{"slug":"investment","term":"Investment"},"next":{"slug":"investment-grade","term":"Investment Grade"}}')}}]);